 for(let i=this.fx.length-1;i>=0;i--){let f=this.fx[i];f.life-=fxdt;let q=this.point(f.x,f.y);c.globalAlpha=clamp(f.life/(f.max*.6),0,1);if(f.kind==='atlas'){const im=this.assets['combat-fx-v4'];if(im){const frame=Math.min(3,Math.floor((1-f.life/f.max)*4)),sw=im.width/4,sh=im.height/4,d=f.r*this.scale,dh=f.ground?Math.min(d,this.scale*3.8):d;c.save();c.translate(q.x,q.y);c.scale(f.dir||1,1);c.globalCompositeOperation='screen';c.drawImage(im,frame*sw+2,f.row*sh+2,sw-4,sh-4,-d/2,f.ground?-dh*.88:-dh/2,d,dh);c.restore();}}else if(f.kind==='shock'){f.r+=dt*15;c.strokeStyle=f.color;c.lineWidth=Math.max(1,4*f.life/f.max);c.beginPath();c.ellipse(q.x,q.y,f.r*this.scale,f.r*this.scale*(f.flat?.24:1),0,0,Math.PI*2);c.stroke();}else if(f.kind==='spark'){f.x+=f.vx*fxdt;f.y+=f.vy*fxdt;f.vy-=9*fxdt;c.fillStyle=f.color;c.fillRect(q.x,q.y,Math.abs(f.vx)>3?3:2,1);}else if(f.kind==='ring'){f.r+=9*fxdt;c.strokeStyle=f.color;c.lineWidth=2;c.beginPath();c.arc(q.x,q.y,f.r*this.scale,0,Math.PI*2);c.stroke();}else if(f.kind==='thrust'){c.fillStyle=f.color;c.fillRect(q.x,q.y,Math.round(f.dir*f.r*this.scale),2);c.fillStyle='#fffce1';c.fillRect(q.x,q.y,Math.round(f.dir*f.r*this.scale),1);}else{c.save();c.translate(q.x,q.y);c.scale(f.dir,1);c.strokeStyle=f.color;c.lineWidth=3;c.beginPath();c.arc(0,0,f.r*this.scale*.9,-1.05,1.05);c.stroke();c.strokeStyle='#fff5d8';c.lineWidth=1;c.beginPath();c.arc(0,0,f.r*this.scale*.95,-.9,.9);c.stroke();c.restore();}c.globalAlpha=1;if(f.life<=0)this.fx.splice(i,1);}
